import test from 'node:test';
import assert from 'node:assert/strict';
import { watchChannel } from './client.js';

function createHarness({ channel = 'selected', post = () => {} } = {}) {
  const jobs = [];
  const abortReasons = [];
  let releaseCount = 0;
  let handlers;
  let signal;
  let connectedChannel;

  const connect = (nextChannel, nextSignal, nextHandlers) => {
    connectedChannel = nextChannel;
    signal = nextSignal;
    handlers = nextHandlers;

    return {
      abort(reason) {
        abortReasons.push(reason);
      },
      release() {
        releaseCount += 1;
      },
    };
  };

  const schedule = job => {
    assert.equal(typeof job, 'function');
    jobs.push(job);
  };

  const handle = watchChannel({ channel, connect, schedule, post });

  return {
    handle,
    jobs,
    abortReasons,
    get releaseCount() {
      return releaseCount;
    },
    get handlers() {
      return handlers;
    },
    get signal() {
      return signal;
    },
    get connectedChannel() {
      return connectedChannel;
    },
  };
}

function runAllJobs(jobs) {
  while (jobs.length > 0) {
    jobs.shift()();
  }
}

function runAllJobsIgnoringThrows(jobs) {
  const errors = [];

  while (jobs.length > 0) {
    try {
      jobs.shift()();
    } catch (error) {
      errors.push(error);
    }
  }

  return errors;
}

async function outcomeAfterImmediate(promise) {
  const pending = Symbol('pending');
  const outcome = await Promise.race([
    promise.then(
      value => ({ state: 'fulfilled', value }),
      error => ({ state: 'rejected', error }),
    ),
    new Promise(resolve => setImmediate(() => resolve(pending))),
  ]);

  return outcome === pending ? { state: 'pending' } : outcome;
}

test('invalid options throw TypeError synchronously', () => {
  const fn = () => {};
  const invalidOptions = [
    undefined,
    null,
    {},
    { channel: 1, connect: fn, schedule: fn, post: fn },
    { channel: new String('x'), connect: fn, schedule: fn, post: fn },
    { channel: 'x', connect: null, schedule: fn, post: fn },
    { channel: 'x', connect: fn, schedule: null, post: fn },
    { channel: 'x', connect: fn, schedule: fn, post: null },
  ];

  for (const options of invalidOptions) {
    assert.throws(() => watchChannel(options), TypeError);
  }
});

test('connect errors propagate synchronously', () => {
  const failure = new Error('connect failed');

  assert.throws(
    () =>
      watchChannel({
        channel: 'selected',
        connect() {
          throw failure;
        },
        schedule() {},
        post() {},
      }),
    error => error === failure,
  );
});

test('connect receives the channel, a fresh signal, and callback handlers', async () => {
  const connections = [];

  function connect(channel, signal, handlers) {
    connections.push({ channel, signal, handlers });
    return {
      abort() {},
      release() {},
    };
  }

  const options = {
    channel: 'selected',
    connect,
    schedule() {},
    post() {},
  };

  const first = watchChannel(options);
  const second = watchChannel(options);

  assert.equal(connections.length, 2);

  for (const connection of connections) {
    assert.equal(connection.channel, 'selected');
    assert.ok(connection.signal instanceof AbortSignal);
    assert.equal(connection.signal.aborted, false);
    assert.equal(typeof connection.handlers.data, 'function');
    assert.equal(typeof connection.handlers.end, 'function');
    assert.equal(typeof connection.handlers.error, 'function');
  }

  assert.notStrictEqual(connections[0].signal, connections[1].signal);

  first.stop('cleanup');
  second.stop('cleanup');
  await Promise.all([first.finished, second.finished]);
});

test('matching payloads are deferred, ordered, and preserve object identity', async () => {
  const posted = [];
  let insideData = false;

  const harness = createHarness({
    post(payload) {
      assert.equal(insideData, false);
      posted.push(payload);
    },
  });

  const objectPayload = { value: 42 };

  insideData = true;
  harness.handlers.data({ channel: 'other', payload: 'ignored' });
  harness.handlers.data({ channel: 'selected', payload: 'first' });
  harness.handlers.data({ channel: 'selected', payload: objectPayload });
  harness.handlers.data({ channel: 'selected', payload: 'third' });
  insideData = false;

  assert.deepEqual(posted, []);
  assert.ok(harness.jobs.length > 0);

  runAllJobs(harness.jobs);

  assert.equal(posted.length, 3);
  assert.equal(posted[0], 'first');
  assert.strictEqual(posted[1], objectPayload);
  assert.equal(posted[2], 'third');

  harness.handle.stop('cleanup');
  await harness.handle.finished;
});

test('frames received reentrantly retain their arrival order', async () => {
  const posted = [];
  let harness;

  harness = createHarness({
    post(payload) {
      posted.push(payload);

      if (payload === 'first') {
        harness.handlers.data({
          channel: 'selected',
          payload: 'third',
        });
      }
    },
  });

  harness.handlers.data({ channel: 'selected', payload: 'first' });
  harness.handlers.data({ channel: 'selected', payload: 'second' });

  runAllJobs(harness.jobs);
  assert.deepEqual(posted, ['first', 'second', 'third']);

  harness.handle.stop('cleanup');
  await harness.handle.finished;
});

test('end drains accepted frames, releases once, and ignores later callbacks', async () => {
  const posted = [];
  const harness = createHarness({
    post(payload) {
      posted.push(payload);
    },
  });

  harness.handlers.data({ channel: 'selected', payload: 'first' });
  harness.handlers.data({ channel: 'selected', payload: 'second' });
  harness.handlers.end();

  assert.deepEqual(posted, []);
  assert.equal(harness.releaseCount, 0);
  assert.deepEqual(
    await outcomeAfterImmediate(harness.handle.finished),
    { state: 'pending' },
  );

  harness.handlers.data({ channel: 'selected', payload: 'late' });
  harness.handlers.error(new Error('late error'));
  harness.handlers.end();

  runAllJobs(harness.jobs);

  assert.deepEqual(posted, ['first', 'second']);
  assert.deepEqual(await harness.handle.finished, { state: 'ended' });
  assert.equal(harness.releaseCount, 1);
  assert.deepEqual(harness.abortReasons, []);

  harness.handle.stop('too late');
  assert.equal(harness.releaseCount, 1);
  assert.deepEqual(harness.abortReasons, []);
});

test('end called from post still drains frames already received', async () => {
  const posted = [];
  let harness;

  harness = createHarness({
    post(payload) {
      posted.push(payload);

      if (payload === 'first') {
        harness.handlers.end();
      }
    },
  });

  harness.handlers.data({ channel: 'selected', payload: 'first' });
  harness.handlers.data({ channel: 'selected', payload: 'second' });

  runAllJobs(harness.jobs);

  assert.deepEqual(posted, ['first', 'second']);
  assert.deepEqual(await harness.handle.finished, { state: 'ended' });
  assert.equal(harness.releaseCount, 1);
  assert.deepEqual(harness.abortReasons, []);
});

test('stop aborts and releases synchronously and suppresses all later posts', async () => {
  const posted = [];
  const reason = { kind: 'cancelled' };
  const harness = createHarness({
    post(payload) {
      posted.push(payload);
    },
  });

  harness.handlers.data({ channel: 'selected', payload: 'queued' });
  harness.handle.stop(reason);

  assert.equal(harness.signal.aborted, true);
  assert.strictEqual(harness.signal.reason, reason);
  assert.deepEqual(harness.abortReasons, [reason]);
  assert.equal(harness.releaseCount, 1);

  harness.handlers.data({ channel: 'selected', payload: 'late' });
  harness.handlers.error(new Error('late error'));
  harness.handlers.end();
  runAllJobs(harness.jobs);

  assert.deepEqual(posted, []);

  const result = await harness.handle.finished;
  assert.equal(result.state, 'stopped');
  assert.strictEqual(result.reason, reason);

  harness.handle.stop({ kind: 'second reason' });
  assert.deepEqual(harness.abortReasons, [reason]);
  assert.equal(harness.releaseCount, 1);
  assert.strictEqual((await harness.handle.finished).reason, reason);
});

test('stop called from post keeps the current delivery and drops the rest', async () => {
  const posted = [];
  const reason = { kind: 'stopped in post' };
  let harness;

  harness = createHarness({
    post(payload) {
      posted.push(payload);

      if (payload === 'first') {
        harness.handle.stop(reason);
      }
    },
  });

  harness.handlers.data({ channel: 'selected', payload: 'first' });
  harness.handlers.data({ channel: 'selected', payload: 'second' });
  harness.handlers.data({ channel: 'selected', payload: 'third' });

  runAllJobs(harness.jobs);

  assert.deepEqual(posted, ['first']);
  const result = await harness.handle.finished;
  assert.equal(result.state, 'stopped');
  assert.strictEqual(result.reason, reason);
  assert.deepEqual(harness.abortReasons, [reason]);
  assert.equal(harness.releaseCount, 1);
});

test('a throw after post calls stop preserves the stopped result', async () => {
  const reason = { kind: 'chosen cancellation' };
  const failure = new Error('post failed after stopping');
  const posted = [];
  let harness;

  harness = createHarness({
    post(payload) {
      posted.push(payload);
      harness.handle.stop(reason);
      throw failure;
    },
  });

  harness.handlers.data({ channel: 'selected', payload: 'first' });
  harness.handlers.data({ channel: 'selected', payload: 'second' });

  runAllJobsIgnoringThrows(harness.jobs);

  assert.deepEqual(posted, ['first']);

  const result = await harness.handle.finished;
  assert.equal(result.state, 'stopped');
  assert.strictEqual(result.reason, reason);
  assert.deepEqual(harness.abortReasons, [reason]);
  assert.equal(harness.releaseCount, 1);
});

test('source error rejects with the same value and cancels queued delivery', async () => {
  const posted = [];
  const failure = new Error('source failed');
  const harness = createHarness({
    post(payload) {
      posted.push(payload);
    },
  });

  harness.handlers.data({ channel: 'selected', payload: 'queued' });

  const rejection = assert.rejects(
    harness.handle.finished,
    error => error === failure,
  );

  harness.handlers.error(failure);

  assert.equal(harness.releaseCount, 1);
  assert.deepEqual(harness.abortReasons, []);

  harness.handlers.data({ channel: 'selected', payload: 'late' });
  harness.handlers.end();
  runAllJobs(harness.jobs);

  await rejection;
  assert.deepEqual(posted, []);

  harness.handle.stop('too late');
  assert.equal(harness.releaseCount, 1);
  assert.deepEqual(harness.abortReasons, []);
});

test('post error rejects with the same value and drops remaining deliveries', async () => {
  const failure = new Error('post failed');
  const attempted = [];
  const harness = createHarness({
    post(payload) {
      attempted.push(payload);

      if (payload === 'first') {
        throw failure;
      }
    },
  });

  harness.handlers.data({ channel: 'selected', payload: 'first' });
  harness.handlers.data({ channel: 'selected', payload: 'second' });

  const rejection = assert.rejects(
    harness.handle.finished,
    error => error === failure,
  );

  runAllJobsIgnoringThrows(harness.jobs);
  await rejection;

  assert.deepEqual(attempted, ['first']);
  assert.equal(harness.releaseCount, 1);
  assert.deepEqual(harness.abortReasons, []);

  harness.handlers.data({ channel: 'selected', payload: 'late' });
  harness.handlers.end();
  runAllJobsIgnoringThrows(harness.jobs);

  assert.deepEqual(attempted, ['first']);
  assert.equal(harness.releaseCount, 1);
});
